$results=[];$scenario=function(string $name,callable $test)use(&$results):void{try{$test();$results[$name]=true;echo "PASS $name\n";}catch(Throwable $e){$results[$name]=false;fwrite(STDERR,"FAIL $name ".$e->getMessage()."\n");}};$assert=function(bool $ok,string $message='assertion failed'):void{if(!$ok)throw new RuntimeException($message);};
$reset=function()use($pdo):void{$pdo->exec('SET FOREIGN_KEY_CHECKS=0');foreach(['queue_core_dispatch_journal','queue_core_attempts','queue_core_events','queue_core_jobs','queue_core_producer_checkpoints','queue_core_execution_leases','meli_tokens','api_remote_permits','api_rhythm_states','api_rhythm_penalties','api_budget_windows','api_workload_estimates'] as $t)$pdo->exec("TRUNCATE TABLE `$t`");$pdo->exec('SET FOREIGN_KEY_CHECKS=1');$pdo->exec("UPDATE queue_core_scheduler_state SET cycle_position=0,generation=0 WHERE scheduler_key='default'");$pdo->exec("INSERT INTO queue_core_execution_leases(lease_key,generation) VALUES('global',0)");AppSettingsService::clearCache();SchemaInspectorService::clearCache();};
$parallel=function(string $mode):array{$start=(int)floor(microtime(true)*1000)+500;$procs=[];$outputs=[];for($i=0;$i<2;$i++){$pipes=[];$proc=proc_open([PHP_BINARY,__DIR__.'/fixtures/queue_core_race_worker.php',$mode,'worker-'.$i,(string)$start],[1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__));if(!is_resource($proc))throw new RuntimeException('parallel worker did not start');$procs[]=[$proc,$pipes];}foreach($procs as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($proc);if($code!==0)throw new RuntimeException('parallel worker failed: '.$err);$outputs[]=json_decode((string)$out,true,32,JSON_THROW_ON_ERROR);}return $outputs;};
$job=function(int $account,string $lane,string $key,int $max=5,int $company=1):QueueJob{return new QueueJob($company,$account,'test_work','test_resource',$key,$lane,0,$key,'v1','test',null,['key'=>$key],[],$max);};
$request=function(string $worker,int $max=1,float $deadline=0,array $ids=[]):QueueRunRequest{return new QueueRunRequest('test',$worker,$max,$deadline>0?$deadline:microtime(true)+30,30,$ids);};

$scenario('fifo_order',function()use($reset,$assert,$job,$request,$pdo){$reset();$r=new QueueCoreRepository($pdo);$ids=[];foreach(['a','b','c'] as $key)$ids[]=$r->enqueue($job(1,'normal',$key));$seen=[];foreach(range(1,3) as $n){$c=$r->claimNext($request('fifo'.$n),['test_work']);$seen[]=$c?->id;$a=$r->beginAttempt($c,'test');$r->finish($c,$a,QueueResult::completed());}$assert($seen===$ids,'eligible jobs did not preserve FIFO');});
$scenario('fifo_no_priority_jump',function()use($reset,$assert,$request,$pdo){$reset();$r=new QueueCoreRepository($pdo);$a=$r->enqueue(new QueueJob(1,1,'test_work','r','a','historical_backfill',-100,'a','v1','test',null,[],[],3));$r->enqueue(new QueueJob(1,1,'test_work','r','b','fresh_orders',999,'b','v1','test',null,[],[],3));$assert($r->claimNext($request('fifo-priority'),['test_work'])?->id===$a,'lane or priority jumped FIFO');});
$scenario('blocked_head_does_not_block',function()use($reset,$assert,$job,$request,$pdo){$reset();$r=new QueueCoreRepository($pdo);$a=$r->enqueue($job(1,'normal','blocked'));$pdo->prepare("UPDATE queue_core_jobs SET state='waiting_oauth',wait_refresh_version=1 WHERE id=?")->execute([$a]);$b=$r->enqueue($job(1,'normal','ready'));$assert($r->claimNext($request('fifo-blocked'),['test_work'])?->id===$b);});
$scenario('fifo_concurrent_claim',function()use($pdo,$reset,$assert,$job,$parallel){$reset();$r=new QueueCoreRepository($pdo);$first=$r->enqueue($job(1,'normal','claim-a'));$second=$r->enqueue($job(2,'fresh_orders','claim-b'));$rows=$parallel('claim');$ids=array_values(array_filter(array_map(static fn(array $row):int=>(int)($row['id']??0),$rows)));sort($ids);$assert($ids===[$first,$second],'concurrent workers did not claim the first two FIFO jobs');});
