$scenario('lease_expiry_reclaim',function()use($pdo,$reset,$assert,$job,$request){$reset();$r=new QueueCoreRepository($pdo);$id=$r->enqueue($job(1,'normal','lease'));$r->claimNext($request('old'),['test_work']);$pdo->exec("UPDATE queue_core_jobs SET lease_expires_at=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE id=$id");$rec=$r->recoverStale();$pdo->exec("UPDATE queue_core_jobs SET next_attempt_at=UTC_TIMESTAMP(3),available_at=UTC_TIMESTAMP(3) WHERE id=$id");$new=$r->claimNext($request('new'),['test_work']);$assert($rec['retry_wait']===1&&$new?->leaseGeneration===2);});
