$scenario('bad_row_does_not_block',function()use($pdo,$reset,$assert){$reset();$r=new QueueCoreRepository($pdo);$make=fn(string $key):QueueJob=>new QueueJob(1,1,'manual_exact','fixture',$key,'normal',0,$key,'v1','test',null,['key'=>$key],[],3);$bad=$r->enqueue($make('bad'));$good=$r->enqueue($make('good'));$registry=new QueueHandlerRegistry();$registry->register('manual_exact',new class implements QueueHandler{public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return ($j->payload['key']??'')==='bad'?QueueResult::dead('poison'):QueueResult::completed(1);}});$s=(new QueueRunner($r,$registry))->run(new QueueRunRequest('test','worker',2,microtime(true)+20));$assert(($r->job($bad)['state']??'')==='dead'&&($r->job($good)['state']??'')==='completed'&&$s['claimed']===2);});
