$scenario('producer_checkpoint_overlap',function()use($pdo,$reset,$assert){$reset();$r=new QueueCoreRepository($pdo);$producer=new FreshOrdersProducer($pdo,$r,300,3600);$producer->scheduleDueAccounts();$row=$pdo->query("SELECT window_from,window_to,generation FROM queue_core_producer_checkpoints WHERE producer_key='fresh_orders' AND meli_account_id=1")->fetch();$from=is_array($row)?strtotime((string)$row['window_from'].' UTC'):false;$assert(is_array($row)&&$from!==false&&$from<=time()-3500);$gateway=new class implements FreshOrdersGateway{public function fetch(int $c,int $a,string $f,string $t,?string $cursor,int $limit):array{return ['orders'=>[['id'=>'90001','date_created'=>$f,'input_version'=>'stable']], 'next_cursor'=>null,'has_more'=>false];}};$registry=new QueueHandlerRegistry();$registry->register('fresh_orders_discovery',new FreshOrdersDiscoveryHandler($pdo,$r,$gateway));$runner=new QueueRunner($r,$registry);$runner->run(new QueueRunRequest('test','producer-one',1,microtime(true)+20,30,[],['fresh_orders_discovery'],1));$pdo->exec("UPDATE queue_core_producer_checkpoints SET next_due_at=UTC_TIMESTAMP(3) WHERE producer_key='fresh_orders' AND meli_account_id=1");$producer->scheduleDueAccounts();$runner->run(new QueueRunRequest('test','producer-two',1,microtime(true)+20,30,[],['fresh_orders_discovery'],1));$count=(int)$pdo->query("SELECT COUNT(*) FROM queue_core_jobs WHERE work_type='order_exact' AND meli_account_id=1 AND resource_id='90001'")->fetchColumn();$assert($count===1,'overlap produced a duplicate order job');});
$scenario('producer_downtime_catchup',function()use($pdo,$reset,$assert){$reset();$r=new QueueCoreRepository($pdo);$pdo->exec("INSERT INTO queue_core_producer_checkpoints(producer_key,company_id,meli_account_id,watermark_at,next_due_at,generation) VALUES('fresh_orders',1,1,DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 2 DAY),UTC_TIMESTAMP(3),7)");(new FreshOrdersProducer($pdo,$r,300,3600))->scheduleDueAccounts();$raw=$pdo->query("SELECT payload_json FROM queue_core_jobs WHERE meli_account_id=1 AND work_type='fresh_orders_discovery' LIMIT 1")->fetchColumn();$payload=is_string($raw)?json_decode($raw,true):null;$from=is_array($payload)&&isset($payload['from'])?strtotime((string)$payload['from'].' UTC'):false;$assert($from!==false&&$from<=time()-2*86400-250,'downtime window was not materialized');});
