$scenario('manual_allowed_automation_cron_forbidden',function()use($pdo,$reset,$assert){$reset();$root=dirname(__DIR__);$automationMarker=$root.'/PAUSE_ERP_AUTOMATION';$apiMarker=$root.'/PAUSE_MELI_API';$savedApi=is_file($apiMarker)?file_get_contents($apiMarker):null;@unlink($apiMarker);putenv('APP_KEY=queue-core-fake-transport-key');$encrypted=Crypto::encrypt('fake-access-token');$pdo->prepare("INSERT INTO meli_tokens(meli_account_id,access_token_encrypted,expires_at,refresh_version) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 6 HOUR),1)")->execute([1,$encrypted]);$pdo->exec("INSERT INTO app_settings(setting_key,setting_value,is_encrypted,setting_group) VALUES('api.guard.enabled','0',0,'api') ON DUPLICATE KEY UPDATE setting_value='0',is_encrypted=0");AppSettingsService::clearCache();$r=new QueueCoreRepository($pdo);$manualId=$r->enqueue(new QueueJob(1,1,'manual_exact','fixture','1','normal',0,'manual-stop','v1','test',null,[],[],3));$cronId=$r->enqueue(new QueueJob(1,1,'order_exact','order','2','fresh_orders',0,'cron-stop','v1','test',null,[],[],3));$transport=new class implements MeliHttpTransportInterface{public int $calls=0;public function request(string $method,string $url,array $data,array $headers,bool $form,array $timeouts):array{App\QueueCore\QueueCoreDispatchFence::beforeTransport($method,(string)(parse_url($url,PHP_URL_PATH)?:'/'));App\QueueCore\QueueCoreDispatchFence::transportStarted($method,(string)(parse_url($url,PHP_URL_PATH)?:'/'));$this->calls++;return ['status'=>200,'body'=>['id'=>'123'],'headers'=>[],'curl_error'=>'','duration_ms'=>1,'wire_bytes'=>2,'decoded_bytes'=>2];}};$client=new MeliApiClient(1,$transport);$handler=new class($client) implements QueueHandler{public function __construct(private MeliApiClient $client){}public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{$this->client->get('/orders/123',[],['job_type'=>'manual_exact']);return QueueResult::completed(1,1);}};$registry=new QueueHandlerRegistry();$registry->register('manual_exact',$handler);$registry->register('order_exact',$handler);file_put_contents($automationMarker,'test');try{$manual=(new QueueRunner($r,$registry))->run(new QueueRunRequest('manual','manual-stop',1,microtime(true)+10,30,[$manualId],['manual_exact'],1));$cron=(new QueueRunner($r,$registry))->run(new QueueRunRequest('cron_v4','cron-stop',1,microtime(true)+10,30,[$cronId],['order_exact'],1));}finally{@unlink($automationMarker);if(is_string($savedApi))file_put_contents($apiMarker,$savedApi);else @unlink($apiMarker);}$assert($manual['completed']===1&&$transport->calls===1&&$cron['claimed']===0&&$cron['reason']==='automation_stopped','manual fake GET or Cron Automation Stop contract failed');});
$scenario('waiting_oauth_resumes_same_job',function()use($pdo,$reset,$assert){$reset();$pdo->exec("INSERT INTO meli_tokens(meli_account_id,access_token_encrypted,expires_at,refresh_version) VALUES(1,'x',DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 HOUR),4)");$r=new QueueCoreRepository($pdo);$id=$r->enqueue(new QueueJob(1,1,'fresh_orders_discovery','orders_window',null,'fresh_orders',0,'oauth-wait','v1','test',null,[],[],3));$registry=new QueueHandlerRegistry();$handler=new class implements QueueHandler{public int $calls=0;public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{$this->calls++;if($this->calls===1)throw new OAuthRefreshRequiredException($j->meliAccountId);return QueueResult::completed(1);}};$registry->register('fresh_orders_discovery',$handler);$runner=new QueueRunner($r,$registry);$first=$runner->run(new QueueRunRequest('test','oauth-one',1,microtime(true)+10));$assert(($r->job($id)['state']??'')==='waiting_oauth'&&$handler->calls===1);$busy=$runner->run(new QueueRunRequest('test','oauth-busy',1,microtime(true)+10));$assert($busy['claimed']===0);$pdo->exec("UPDATE meli_tokens SET refresh_version=5,expires_at=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 6 HOUR) WHERE meli_account_id=1");$second=$runner->run(new QueueRunRequest('test','oauth-two',1,microtime(true)+10));$assert($second['completed']===1&&$handler->calls===2&&($r->job($id)['state']??'')==='completed');});
$scenario('producer_due_before_limit',function()use($pdo,$reset,$assert){$reset();$insert=$pdo->prepare("INSERT INTO meli_accounts(id,company_id,meli_user_id,account_name,status) VALUES(?,?,?,?, 'conectado') ON DUPLICATE KEY UPDATE company_id=VALUES(company_id),meli_user_id=VALUES(meli_user_id),account_name=VALUES(account_name),status=VALUES(status)");for($i=1;$i<=30;$i++)$insert->execute([$i,(int)ceil($i/10),(string)(1000+$i),'A'.$i]);$cp=$pdo->prepare("INSERT INTO queue_core_producer_checkpoints(producer_key,company_id,meli_account_id,next_due_at,generation) VALUES('fresh_orders',?,?,DATE_ADD(UTC_TIMESTAMP(3),INTERVAL ? SECOND),0)");for($i=1;$i<=30;$i++)$cp->execute([(int)ceil($i/10),$i,$i===25?-1:3600]);$result=(new FreshOrdersProducer($pdo,new QueueCoreRepository($pdo)))->scheduleDueAccounts(1);$account=(int)$pdo->query("SELECT meli_account_id FROM queue_core_jobs WHERE work_type='fresh_orders_discovery' LIMIT 1")->fetchColumn();$assert($result['enqueued']===1&&$account===25);});
